import sys
from collections import defaultdict, deque

# Read input
n, q = map(int, sys.stdin.readline().split())
a = list(map(int, sys.stdin.readline().split()))
edges = defaultdict(list)

# Read edges
for _ in range(n - 1):
    u, v = map(int, sys.stdin.readline().split())
    edges[u].append(v)
    edges[v].append(u)

# Read queries
queries = [list(map(int, sys.stdin.readline().split())) for _ in range(q)]

# LCA preparation
MAXN = n
MAXL = 20  # log2(MAXN) + 1
up = [[-1] * (MAXL + 1) for _ in range(MAXN + 1)]
lvl = [-1] * (MAXN + 1)

def bfs(root):
    queue = deque([root])
    lvl[root] = 0
    while queue:
        v = queue.popleft()
        for u in edges[v]:
            if lvl[u] == -1:
                lvl[u] = lvl[v] + 1
                up[u][0] = v
                queue.append(u)

def lca_preprocess():
    bfs(1)
    for j in range(1, MAXL + 1):
        for i in range(1, MAXN + 1):
            if up[i][j - 1] != -1:
                up[i][j] = up[up[i][j - 1]][j - 1]

def lca(u, v):
    if lvl[u] < lvl[v]:
        u, v = v, u
    for i in range(MAXL, -1, -1):
        if lvl[u] - (1 << i) >= lvl[v]:
            u = up[u][i]
    if u == v:
        return u
    for i in range(MAXL, -1, -1):
        if up[u][i] != up[v][i]:
            u = up[u][i]
            v = up[v][i]
    return up[u][0]

# Preprocess LCA
lca_preprocess()

# Process queries
for u, v in queries:
    ancestor = lca(u, v)
    max_xor = 0
    current = v
    while current != ancestor:
        max_xor = max(max_xor, a[current - 1] ^ a[ancestor - 1])
        current = up[current][0]
    while u != ancestor:
        max_xor = max(max_xor, a[u - 1] ^ a[ancestor - 1])
        u = up[u][0]
    print(max_xor)
